from collections import deque
out=[row[:] for row in grid]
def orbit_value(r,c):
    q=deque([(r,c)]); seen={(r,c)}
    while q:
        x,y=q.popleft()
        if grid[x][y]!=6:return grid[x][y],(x,y)
        neighbors=[(y,x)]
        if 0<=31-x<30: neighbors.append((31-x,y))
        for z in neighbors:
            if z not in seen: seen.add(z); q.append(z)
    return None,seen
vals={}
for r,c in holes:
    v,src=orbit_value(r,c)
    vals[(r,c)]=(v,src)
    if v is not None: out[r][c]=v
